def shell(content,title='Metal Roofing, Siding & Building Products',path='/'):
 return f'''<!doctype html><html lang="en-CA"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>{html.escape(title)} | Domtek</title><meta name="description" content="Domtek metal roofing, siding, wall cladding, PVC panels and building products for residential, agricultural and commercial applications. Supporting Canadian suppliers since 1989."><meta name="theme-color" content="#173a67"><link rel="stylesheet" href="/style.css"><script src="/app.js" defer></script></head><body id="top">{header}<main id="main">{content}</main>{footer}<dialog class="lightbox"><button aria-label="Close image">×</button><img alt="Project image"></dialog></body></html>'''
def write(path,content,title):
 folder='dist'+path;os.makedirs(folder,exist_ok=True);open(folder+'/index.html','w').write(shell(content,title,path).replace('\u2014',' - '))
